local mapper = mapper
local config_dhcprelay = "dhcprelay"

local uci_dhcprelay = mapper("uci_1to1").createConfigMap(config_dhcprelay)
register(uci_dhcprelay)

-- uci.dhcprelay.config.
local dhcprelay_config = {
    config = config_dhcprelay,
    section = "config",
    options = { "serveriface", "clientiface", "enabled", "serverip" }
}

local uci_dhcprelay_config = mapper("uci_1to1").createSimpleMap(dhcprelay_config)
register(uci_dhcprelay_config)

